import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"6.3 备份、恢复与升级","description":"换机器、换版本或误操作都不丢任务、产物和记忆。","frontmatter":{"title":"6.3 备份、恢复与升级","description":"换机器、换版本或误操作都不丢任务、产物和记忆。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/6-3.md","filePath":"delivery/stage-6/6-3.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-6/6-3.md"};function l(d,e,c,s,n,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="_6-3-备份、恢复与升级" tabindex="-1">6.3 备份、恢复与升级 <a class="header-anchor" href="#_6-3-备份、恢复与升级" aria-label="Permalink to &quot;6.3 备份、恢复与升级&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 生成 <code>*.hearth-backup</code> 加密归档；scrypt 派生密钥，AES-256-GCM 加密；恢复先检查 <code>user_version</code>、schema 和 <code>integrity_check</code>，重建投影后再事务复制，失败回滚；旧 <code>/api/backup</code> 返回 <code>410</code>。</li><li><strong>仍未完成：</strong> 归档不包含产物正文、任务工作区、来源正文、发件箱附件和截屏，不是完整可迁移备份；没有版本升级流水线和真实跨版本恢复演练。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让用户可以完整备份、恢复、导出和升级，不因为换机器、版本变化或误操作丢失任务、产物和记忆。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>提供加密备份，包含任务、产物、记忆、设置和必要的授权信息。</li><li>支持完整恢复和选择性导出，恢复后能核对内容是否齐全。</li><li>升级前检查版本兼容性和空间，升级失败可以退回旧版本。</li><li>迁移后验证任务状态、产物、记忆和技能仍然可用。</li><li>提供清楚的备份位置、恢复步骤和失败说明，用户不需要开发者协助。</li><li>用一次完整迁移演练验证：备份、恢复、升级、退回都能完成。</li></ol>',7)])])}const u=a(r,[["render",l]]);export{p as __pageData,u as default};
